      sessionId, credentialId, token: rawToken, ...(rawCsrf ? { csrfToken: rawCsrf } : {}),
      expiresAt: payload.expiresAt,
      ...(fields.authMethod === 'cookie' ? { setCookie: `${COOKIE_NAME}=${rawToken}; Max-Age=${maxAge}; Secure; HttpOnly; SameSite=Strict; Path=/` } : {}),
    });
